import places from "./airportPlaces.json";

// IATA airport code to its ISO country and coordinates, generated by
// scripts/airports.mjs. A separate entry point (`@travelmo/core/airportPlaces`)
// like the zone table: only the reports page needs it, so it loads on demand.
const table = places as unknown as Record<string, [string, number, number]>;

export type AirportPlace = { country: string; lat: number; lon: number };

export function airportPlace(code: string): AirportPlace | undefined {
  const key = code.trim().toUpperCase();
  const found = /^[A-Z]{3}$/.test(key) ? table[key] : undefined;
  return found ? { country: found[0], lat: found[1], lon: found[2] } : undefined;
}
